-- Se puede repetir: no duplica el campo, los documentos ni los enlaces.
BEGIN;

-- El único campo nuevo. Los del nombramiento (cargo, fecha del acta, notario,
-- registro, folio y libro) ya existen: son los de inversiones sociedad.
-- `key` no tiene restricción única en la base: se evita el duplicado a mano.
INSERT INTO docuseal.field (name, key, regex, description, required, relation, type, options)
SELECT 'Nombre de la Sociedad', 'nombreSociedad', NULL,
       'Nombre de la sociedad que compra el vehículo, en mayúsculas. Ej.: TRANSPORTES GARCÍA, SOCIEDAD ANÓNIMA',
       true, '99.05', 'text', NULL
WHERE NOT EXISTS (SELECT 1 FROM docuseal.field WHERE key = 'nombreSociedad');

