ON CONFLICT DO NOTHING;

-- Verificación: 23 documentos de ventas_sociedad, cada uno con sus campos.
SELECT d.id_docuseal, d.nombre_documento, d.genero, count(ddf.id_field) AS campos
FROM docuseal.documents d
LEFT JOIN docuseal.detail_document_field ddf ON ddf.id_document = d.id_docuseal
WHERE d.categoria = 'ventas_sociedad'
GROUP BY d.id_docuseal, d.nombre_documento, d.genero
ORDER BY d.id_docuseal;

COMMIT;
